import type { TaskType } from "@prisma/client";

/**
 * Fixed, reviewed curriculum content for the writing trainer.
 *
 * This module deliberately contains no prompt-generation code. Exercises are
 * authored data: a learner's selection only filters this bank by task, level,
 * and writing micro-skill.
 */
export type PracticeLevel = "B2" | "C1" | "C2";
export const PRACTICE_LEVELS: readonly PracticeLevel[] = ["B2", "C1", "C2"];

export type PracticeExerciseType = "recognize" | "complete" | "transform" | "organize" | "develop" | "produce";
export const PRACTICE_EXERCISE_SEQUENCE: readonly PracticeExerciseType[] = [
  "recognize",
  "complete",
  "transform",
  "organize",
  "develop",
  "produce",
];

export interface PracticeTopic {
  id: string;
  task: TaskType;
  /**
   * The position of this part in the learner-facing construction of its TCF
   * task. This is deliberately independent of CEFR level: B2, C1 and C2
   * practise the same parts with different linguistic and cognitive demands.
   */
  taskPartOrder: number;
  label: string;
  description: string;
  /** The skill is a writing move, never an isolated grammar point. */
  learningGoal: Record<PracticeLevel, string>;
  tags: readonly string[];
}

export interface PracticeExercise {
  id: string;
  task: TaskType;
  level: PracticeLevel;
  skill: string;
  subSkill: string;
  exerciseType: PracticeExerciseType;
  prompt: string;
  instructions: string;
  options: readonly string[];
  correctAnswer: string | readonly string[] | null;
  acceptedAnswers: readonly string[];
  explanation: string;
  targetLanguageFeature: string;
  difficulty: 1 | 2 | 3 | 4 | 5 | 6;
  sequenceOrder: 1 | 2 | 3 | 4 | 5 | 6;
  prerequisiteExerciseId: string | null;
  tags: readonly string[];
  /**
   * Manually authored criteria for open writing. These deliberately replace
   * an automatic correct/incorrect verdict for Develop and Produce steps.
   */
  selfCheck?: readonly string[];
}

const allLevels = (b2: string, c1: string, c2: string): Record<PracticeLevel, string> => ({ B2: b2, C1: c1, C2: c2 });

